1	import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
2	import {
3	  grantAmount,
4	  itemPrice,
5	  presetRubbings,
6	  presetRubbingTypes,
7	  type RubbingDefinition,
8	  type RubbingType,
9	} from "@pirate-sea-race/content/objectives";
10	import { knownGrantKey } from "./economy.js";
11	import { MAX_RECORDED_REFUSALS, RECORDED_REFUSALS, type LedgerDuel, type LedgerPlayer, type LedgerState } from "./state.js";
12	
13	/**
14	 * Deeply frozen objects already found to be plain integer data. They cannot change any more, so a later check skips
15	 * them: successive states share most of their structure, and this keeps checking every step cheap.
16	 */
17	const verified = new WeakSet<object>();
18	
19	/**
20	 * What `hashState` needs: plain objects, arrays, strings, booleans, null and safe integers only. Returns the path to
21	 * the first offending value, or null.
22	 */
23	function nonIntegerData(value: unknown): string | null {
24	  if (value === null || typeof value === "string" || typeof value === "boolean") return null;
25	  if (typeof value === "number") return Number.isSafeInteger(value) ? null : ` = ${value}`;
26	  if (typeof value !== "object") return ` is a ${typeof value}`;
27	  if (verified.has(value)) return null;
28	  let deeplyFrozen = Object.isFrozen(value);
29	  const check = (child: unknown, label: string): string | null => {
30	    const found = nonIntegerData(child);
31	    if (found !== null) return `${label}${found}`;
32	    if (typeof child === "object" && child !== null && !verified.has(child)) deeplyFrozen = false;
33	    return null;
34	  };
35	  if (Array.isArray(value)) {
36	    for (let index = 0; index < value.length; index++) {
37	      const found = check(value[index], `[${index}]`);
38	      if (found !== null) return found;
39	    }
40	  } else {
41	    const prototype = Object.getPrototypeOf(value);
42	    if (prototype !== Object.prototype && prototype !== null) return " is not a plain object";
43	    for (const key in value) {
44	      const found = check((value as Record<string, unknown>)[key], `.${key}`);
45	      if (found !== null) return found;
46	    }
47	  }
48	  if (deeplyFrozen) verified.add(value);
49	  return null;
50	}
51	
52	const facts = new Map<RulesPresetId, { expected: RubbingDefinition[]; types: RubbingType[]; expectedTypes: Map<string, RubbingType> }>();
53	
54	function presetFacts(presetId: RulesPresetId) {
55	  let found = facts.get(presetId);
56	  if (found === undefined) {
57	    const preset = rulesPresets[presetId];
58	    const expected = presetRubbings(preset);
59	    found = { expected, types: presetRubbingTypes(preset), expectedTypes: new Map(expected.map((rubbing) => [rubbing.id, rubbing.type])) };
60	    facts.set(presetId, found);
61	  }
62	  return found;
63	}
64	
65	/**
66	 * Every rule the ledger must keep between operations (§4, §12, §19 "Inventory correctness"), as a list of
67	 * violations; empty when the state is sound:
68	 *
69	 * - every rubbing id of the preset is present exactly once, with its type, and no other rubbing exists;
70	 * - each rubbing has one valid location: its own source, a player still in the match, an existing cache, or a
71	 *   reservation for one of the two players of an unresolved duel;
72	 * - no player holds (owns or has reserved) two rubbings of one type;
73	 * - no cache is empty; a player in an unresolved duel owns nothing outside it, is in only one, and has no channel;
74	 * - gold balances are non-negative integers that, with the gold spent, sum to the gold issued, and the gold issued
75	 *   is exactly one starting purse per player who ever joined plus the recorded grants, so no gold was minted outside
76	 *   the rules;
77	 * - every grant holds a key the ledger knows (an island's ruin, a supply cache) once and pays the rules' amount;
78	 *   (player, request id) is unique, the purchases add up to the gold spent, and a player keeps at most
79	 *   `MAX_RECORDED_REFUSALS` refusals, each a decided one; a player carries 0 to the carry limit of tonics, one effect
80	 *   at most, and none once gone;
81	 * - the state is plain integer data, so `hashState` covers it.
82	 */
83	export function checkLedger(state: LedgerState): string[] {
84	  const problems: string[] = [];
85	  const offending = nonIntegerData(state);
86	  if (offending !== null) problems.push(`state is not plain integer data: state${offending}`);
87	
88	  const { expected, types, expectedTypes } = presetFacts(state.preset);
89	  if (state.types.join(",") !== types.join(",")) problems.push(`types ${state.types.join(",")} are not the preset's ${types.join(",")}`);
90	
91	  const players = new Map<string, LedgerPlayer>();
92	  for (const player of state.players) {
93	    if (players.has(player.id)) problems.push(`duplicate player id ${player.id}`);
94	    players.set(player.id, player);
95	  }
96	  const sources = new Map(state.sources.map((source) => [source.id, source]));
97	  const caches = new Map<string, number>();
98	  for (const cache of state.caches) {
99	    if (caches.has(cache.id)) problems.push(`duplicate cache id ${cache.id}`);
100	    caches.set(cache.id, 0);
101	  }
102	  const duels = new Map<string, LedgerDuel>();
103	  const unresolved = new Map<string, number>();
104	  for (const duel of state.duels) {
105	    if (duels.has(duel.id)) problems.push(`duplicate duel id ${duel.id}`);
106	    duels.set(duel.id, duel);
107	    if (duel.phase !== "settled") for (const id of duel.players) unresolved.set(id, (unresolved.get(id) ?? 0) + 1);
108	  }
109	
110	  const seen = new Map<string, number>();
111	  const holdings = new Map<string, RubbingType[]>();
112	  for (const rubbing of state.rubbings) {
113	    seen.set(rubbing.id, (seen.get(rubbing.id) ?? 0) + 1);
114	    const type = expectedTypes.get(rubbing.id);
115	    if (type === undefined) problems.push(`rubbing ${rubbing.id} is not one of the preset's`);
116	    else if (rubbing.type !== type) problems.push(`rubbing ${rubbing.id} has type ${rubbing.type}, not ${type}`);
117	    if (rubbing.revision < 0) problems.push(`rubbing ${rubbing.id} has revision ${rubbing.revision}`);
118	
119	    const location = rubbing.location;
120	    const where = `rubbing ${rubbing.id}`;
121	    switch (location.kind) {
122	      case "source": {
123	        const source = sources.get(location.sourceId);
124	        if (!source) problems.push(`${where} is at unknown source ${location.sourceId}`);
125	        else if (source.rubbingId !== rubbing.id) problems.push(`${where} is at ${source.id}, which seals ${source.rubbingId}`);
126	        break;
127	      }
128	      case "player": {
129	        const player = players.get(location.playerId);
130	        if (!player) problems.push(`${where} belongs to unknown player ${location.playerId}`);
131	        else if (player.status === "left") problems.push(`${where} belongs to ${player.id}, who left`);
132	        else if (unresolved.has(player.id)) problems.push(`${where} is owned by ${player.id} outside their duel`);
133	        break;
134	      }
135	      case "cache":
136	        if (!caches.has(location.cacheId)) problems.push(`${where} is in unknown cache ${location.cacheId}`);
137	        else caches.set(location.cacheId, caches.get(location.cacheId)! + 1);
138	        break;
139	      case "duel": {
140	        const duel = duels.get(location.duelId);
141	        if (!duel) problems.push(`${where} is reserved in unknown duel ${location.duelId}`);
142	        else if (duel.phase === "settled") problems.push(`${where} is reserved in settled duel ${duel.id}`);
143	        else if (!duel.players.includes(location.playerId)) problems.push(`${where} is reserved for ${location.playerId}, not in ${duel.id}`);
144	        break;
145	      }
146	      default:
147	        problems.push(`${where} has no valid location`);
148	    }
149	    if (location.kind === "player" || location.kind === "duel") {
150	      const held = holdings.get(location.playerId) ?? [];
151	      if (held.includes(rubbing.type)) problems.push(`player ${location.playerId} holds two ${rubbing.type} rubbings`);
152	      holdings.set(location.playerId, [...held, rubbing.type]);
153	    }
154	  }
155	  for (const { id } of expected) {
156	    const count = seen.get(id) ?? 0;
157	    if (count !== 1) problems.push(`rubbing ${id} is present ${count} times`);
158	  }
159	  if (state.rubbings.length !== expected.length) problems.push(`${state.rubbings.length} rubbings instead of ${expected.length}`);
160	  if (state.sources.length !== expected.length) problems.push(`${state.sources.length} sources instead of ${expected.length}`);
161	  if (new Set(state.sources.map((source) => source.rubbingId)).size !== expected.length) problems.push("two sources seal the same rubbing");
162	  for (const [cacheId, count] of caches) if (count === 0) problems.push(`cache ${cacheId} is empty`);
163	
164	  let gold = 0;
165	  for (const player of state.players) {
166	    if (player.gold < 0) problems.push(`player ${player.id} has ${player.gold} gold`);
167	    gold += player.gold;
168	    const inDuels = unresolved.get(player.id) ?? 0;
169	    if (inDuels > 1) problems.push(`player ${player.id} is in ${inDuels} unresolved duels`);
170	    if (player.channel !== null && (player.status !== "connected" || inDuels > 0)) {
171	      problems.push(`player ${player.id} channels while ${inDuels > 0 ? "in a duel" : player.status}`);
172	    }
173	    if ((player.status === "disconnected") !== (player.reservationDeadline !== null)) {
174	      problems.push(`player ${player.id} is ${player.status} with reservation deadline ${player.reservationDeadline}`);
175	    }
176	    if ((player.status === "left") !== (player.exit !== null)) problems.push(`player ${player.id} is ${player.status} with exit ${JSON.stringify(player.exit)}`);
177	    if (player.freshRumors.some((type, index) => !types.includes(type) || player.freshRumors.indexOf(type) !== index)) {
178	      problems.push(`player ${player.id} has fresh rumors ${player.freshRumors.join(",")}`);
179	    }
180	  }
181	  if (state.goldSpent < 0) problems.push(`${state.goldSpent} gold was spent`);
182	  if (gold + state.goldSpent !== state.goldIssued) {
183	    problems.push(`balances sum to ${gold} gold and ${state.goldSpent} was spent, but ${state.goldIssued} was issued`);
184	  }
185	  problems.push(...economyProblems(state, players));
186	
187	  for (const duel of state.duels) {
188	    if (duel.phase === "fighting") {
189	      if (duel.result !== null || duel.settlement !== null) problems.push(`duel ${duel.id} fights with a result`);
190	      for (const playerId of duel.players) {
191	        if (players.get(playerId)?.status === "left") problems.push(`duel ${duel.id} fights on without ${playerId}, who left`);
192	      }
193	    } else if (duel.phase === "choosing") {
194	      if (duel.result?.outcome !== "win" || duel.choiceDeadline === null) problems.push(`duel ${duel.id} chooses without a win`);
195	      else if (players.get(duel.result.winner ?? "")?.status === "left") problems.push(`duel ${duel.id} waits for a winner who left`);
196	    } else if (duel.result === null || duel.settlement === null) {
197	      problems.push(`duel ${duel.id} settled without a result`);
198	    }
199	  }
200	  return problems;
201	}
202	
203	/**
204	 * §11's economy: gold issued only as purses and known, keyed grants; unique requests whose purchases account for the
205	 * gold spent; bounded refusals; and carried tonics.
206	 */
207	function economyProblems(state: LedgerState, players: ReadonlyMap<string, LedgerPlayer>): string[] {
208	  const problems: string[] = [];
209	  if (new Set(state.supplyCaches).size !== state.supplyCaches.length || state.supplyCaches.some((id) => typeof id !== "string" || id === "")) {
210	    problems.push(`supply caches ${JSON.stringify(state.supplyCaches)} are not unique ids`);
211	  }
212	  const keys = new Set<string>();
213	  let minted = 0;
214	  for (const grant of state.grants) {
215	    const key = grant.reason === "ruin" ? `ruin ${grant.sourceKey} for ${grant.playerId}` : `supply cache ${grant.sourceKey}`;
216	    if (keys.has(key)) problems.push(`${key} was granted twice`);
217	    keys.add(key);
218	    if (!knownGrantKey(state, grant.reason, grant.sourceKey)) problems.push(`${key} is not a known ${grant.reason === "ruin" ? "island" : "supply cache"}`);
219	    if (!players.has(grant.playerId)) problems.push(`${key} went to unknown player ${grant.playerId}`);
220	    if (grant.amount !== grantAmount(state.rules, grant.reason)) problems.push(`${key} minted ${grant.amount} gold`);
221	    minted += grant.amount;
222	  }
223	  const purses = state.players.length * state.rules.startingGold;
224	  if (state.goldIssued !== purses + minted) {
225	    problems.push(`${state.goldIssued} gold was issued, but ${state.players.length} purses and the grants make ${purses + minted}`);
226	  }
227	  const requestKeys = new Set<string>();
228	  const refusals = new Map<string, number>();
229	  let spent = 0;
230	  for (const outcome of state.requests) {
231	    const key = `request ${outcome.requestId} of ${outcome.playerId}`;
232	    if (requestKeys.has(key)) problems.push(`${key} was decided twice`);
233	    requestKeys.add(key);
234	    if (!players.has(outcome.playerId)) problems.push(`${key} was made by an unknown player`);
235	    if (outcome.kind === "purchase") {
236	      if (outcome.price !== itemPrice(state.rules, outcome.item)) problems.push(`${key} cost ${outcome.price} gold`);
237	      spent += outcome.price;
238	    } else {
239	      if (!RECORDED_REFUSALS.includes(outcome.rejection)) problems.push(`${key} keeps refusal ${outcome.rejection}`);
240	      refusals.set(outcome.playerId, (refusals.get(outcome.playerId) ?? 0) + 1);
241	    }
242	  }
243	  if (spent !== state.goldSpent) problems.push(`purchases cost ${spent} gold, but ${state.goldSpent} was spent`);
244	  for (const [playerId, count] of refusals) {
